using System.Reflection;
using System.Runtime.InteropServices;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Input;
using Avalonia.Markup.Xaml.Styling;
using Avalonia.Media.Imaging;
using Avalonia.Styling;
using Avalonia.Themes.Fluent;
using Avalonia.Threading;
using Prism.Commands;
using Prism.Core;
using Prism.Core.Form;
using Prism.Kernel;
using Prism.Ribbon;
using Prism.ViewModels;
using Prism.Views;

Native.Initialize();
AppBuilder.Configure<TestApp>().UseHeadless(new AvaloniaHeadlessPlatformOptions {UseHeadlessDrawing=false}).UseSkia().SetupWithoutStarting();
int checks=0;
void Check(bool valid,string message){if(!valid)throw new Exception(message);Console.WriteLine("PASS "+message);checks++;}
AppSettings.Current.Ribbon=new RibbonLayout();AppSettings.Current.Hotkeys.Clear();
AppSettings.Current.Hotkeys["edit.accept"]="Return|global";
Check(Hotkeys.Effective(Hotkeys.Find("edit.accept")!).Gesture=="Enter","saved Return-key bindings migrate to the canonical Enter gesture");AppSettings.Current.Hotkeys.Remove("edit.accept");
var vm=new MainViewModel();var s=vm.Session;
var source=s.AddObject(null,"Workflow form",ObjKind.Form,form:FormOps.Cylinder(20,50,12,5,false));
s.SelectItems([SelItem.Of(source)]);s.StartCommand(()=>new EditFormCommand());var form=(EditFormCommand)s.ActiveCommand!;
var window=new MainWindow{DataContext=vm};
void Key(Key key,KeyModifiers modifiers=KeyModifiers.None)=>typeof(MainWindow).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,[new KeyEventArgs{Key=key,KeyModifiers=modifiers}]);
var selection=vm.Tabs.Single(t=>t.Title=="Freeform").Groups.Single(g=>g.Title=="Select").Items.OfType<RibbonButton>().ToList();
selection=selection.SelectMany(b=>b.Menu??[b]).ToList();
Key(Avalonia.Input.Key.D1);vm.RefreshRibbon();Check(form.SelMode==FormMode.Vertex&&selection.Single(b=>b.Icon=="sel-vertex").IsChecked,"vertex shortcut synchronizes ribbon and Edit Form");
selection.Single(b=>b.Icon=="sel-edge").Invoke();Check(form.SelMode==FormMode.Edge,"ribbon edge mode changes Edit Form mode");
form.Mode.Index=(int)FormMode.Face;vm.RefreshRibbon();Check(selection.Single(b=>b.Icon=="sel-face").IsChecked,"panel face mode updates the ribbon");
Key(Avalonia.Input.Key.D4);Check(form.ObjectSelected&&form.MovingVertices().Count()==form.Work!.V.Count,"Object mode selects the entire editable cage");
Key(Avalonia.Input.Key.W);Check(form.TransformMode.Index==0,"W selects Move");Key(Avalonia.Input.Key.E);Check(form.TransformMode.Index==1,"E selects Rotate within Freeform");Key(Avalonia.Input.Key.R);Check(form.TransformMode.Index==2,"R selects Scale");
Key(Avalonia.Input.Key.D3);form.Faces.Add(0);form.OnChanged();int beforeFaces=form.Work!.F.Count;
Key(Avalonia.Input.Key.X,KeyModifiers.Alt);Check(form.Work.F.Count>beforeFaces,"Alt+X extrudes the selected cage face");
form.TryUndo();Key(Avalonia.Input.Key.D2);
var edge=form.Work!.Edges().First(e=>Math.Abs(form.Work.V[e.a].Z-form.Work.V[e.b].Z)<.001);long edgeKey=SubdMesh.Key(edge.a,edge.b);
form.Edges.Add(edgeKey);form.OnChanged();Check(!form.ShowTriangles,"surface triangles are hidden by default while editing");
Check(!form.Params.Single(p=>p.Label=="Crease sharpness").IsVisible,"crease amount does not occupy the main Edit Form page");
var commandPanel=new CommandPanel{DataContext=vm};var panelWindow=new Window{Width=394,Height=700,Content=commandPanel};panelWindow.Show();Dispatcher.UIThread.RunJobs();
Key(Avalonia.Input.Key.C);var amount=(NumberParam)form.Params.Single(p=>p.Label=="Crease sharpness");
Check(form.HasPanelStep&&form.DisplayTitle=="Crease"&&form.Params.Count(p=>p.IsVisible)==1&&!form.HasGizmoOptions,"C opens a focused Crease page");
amount.Value=.35;Check(Math.Abs(form.Work!.Crease[edgeKey]-.35)<1e-9,"fractional crease strength previews live");
Dispatcher.UIThread.RunJobs();
string output=Path.GetFullPath("artifacts/freeform-workflow-review");Directory.CreateDirectory(output);
foreach(var theme in new[]{ThemeVariant.Dark,ThemeVariant.Light}){Application.Current!.RequestedThemeVariant=theme;Dispatcher.UIThread.RunJobs();using var bitmap=new RenderTargetBitmap(new PixelSize(394,700));bitmap.Render(commandPanel);bitmap.Save(Path.Combine(output,"crease-"+theme.Key+".png"));}
Key(Avalonia.Input.Key.Escape);Check(ReferenceEquals(s.ActiveCommand,form)&&!form.HasPanelStep&&!form.Work!.Crease.ContainsKey(edgeKey)&&form.Edges.Contains(edgeKey),"Escape cancels only Crease and restores Edit Form and its selection");
Key(Avalonia.Input.Key.C);amount.Value=.65;Key(Avalonia.Input.Key.Enter);
Check(ReferenceEquals(s.ActiveCommand,form)&&!form.HasPanelStep&&Math.Abs(form.Work!.Crease.GetValueOrDefault(edgeKey)-.65)<1e-9,$"Enter applies Crease and returns to the same editor (active={s.ActiveCommand?.Title}, panel={form.HasPanelStep}, sharpness={form.Work!.Crease.GetValueOrDefault(edgeKey)})");
Check(form.Mode.IsVisible&&!amount.IsVisible&&form.Slots[0].IsVisible,"return restores the main panel controls");
form.OpenCrease();amount.Value=0;s.AcceptCommandPanel();Check(!form.Work!.Crease.ContainsKey(edgeKey),"zero sharpness removes a crease");
form.TryUndo();Check(Math.Abs(form.Work!.Crease[edgeKey]-.65)<1e-9,"crease removal is one local undo step");
form.OpenCrease();amount.Value=2;form.TryUndo();Check(!form.HasPanelStep&&Math.Abs(form.Work!.Crease[edgeKey]-.65)<1e-9,"Undo during Crease cancels its preview without leaving stale panel state");
var overlay=new Overlay();form.Tool!.BuildOverlay(s,overlay);Check(overlay.Lines.Any(l=>l.Color==0xEE101923&&l.Width>=4.5f)&&overlay.Lines.Any(l=>l.Color==0xFFE2F1FF),"cage lines include a contrasting halo and bright core");
var mid=(form.Work!.V[edge.a]+form.Work.V[edge.b])*.5;var screen=s.Camera.Project(mid)!.Value;
form.Tool.PointerDown(s,new(screen.x,screen.y,true,false,false,false,2));form.Tool.PointerUp(s,new(screen.x,screen.y,false,false,false,false));
Check(form.Edges.Count>1,"double-clicking an edge selects its loop through the pointer path");
Key(Avalonia.Input.Key.D1);var vertexScreen=s.Camera.Project(form.Work.V[edge.a])!.Value;
form.Tool.PointerDown(s,new(vertexScreen.x,vertexScreen.y,true,false,false,false,2));form.Tool.PointerUp(s,new(vertexScreen.x,vertexScreen.y,false,false,false,false));Check(form.Verts.Count>1,"double-clicking a vertex selects a connected vertex chain");
Key(Avalonia.Input.Key.D3);var faceScreen=s.Camera.Project(form.Work.FaceCenter(0))!.Value;form.SelectComponentLoop(0,false,faceScreen.x,faceScreen.y);Check(form.Faces.Count>1,"quad face selection expands to a face strip");
form.Faces.Clear();form.Faces.Add(0);form.OnChanged();int unmodifiedFaces=form.Work.F.Count;
AppSettings.Current.Hotkeys["form.extrude"]="Shift+X|freeform";
Key(Avalonia.Input.Key.X,KeyModifiers.Alt);Check(form.Work.F.Count==unmodifiedFaces,"remapping extrusion disables the shipped Freeform shortcut");
Key(Avalonia.Input.Key.X,KeyModifiers.Shift);Check(form.Work.F.Count>unmodifiedFaces,"the customized Freeform shortcut executes extrusion");
AppSettings.Current.Hotkeys.Remove("form.extrude");form.TryUndo();
var local=form.Work.Clone();s.CommitCommand();Check(s.ActiveCommand==null&&s.Find(source.Id)!.Form!.Crease.Count==local.Crease.Count,"finishing Edit Form commits its accumulated edits");s.Undo();Check(s.Find(source.Id)!.Form!.Crease.Count==0,"document undo restores the original cage");
Key(Avalonia.Input.Key.X,KeyModifiers.Alt);Check(s.ActiveCommand is ExtrudeCommand,"Alt+X starts normal Extrude outside Freeform editing");s.CancelCommand();
s.EnterSketch(Plane3.XY);Key(Avalonia.Input.Key.X,KeyModifiers.Alt);Check(s.ActiveCommand==null&&s.Sketch!=null,"normal Extrude shortcut does not interrupt a sketch");s.ExitSketch(false);
Check(Hotkeys.Actions.Where(a=>a.Scope==Hotkeys.Freeform).All(a=>Hotkeys.FindConflict(a.Id,a.Default,a.Scope)==null),"Freeform defaults have no shortcut conflicts in their scope");
var smooth=FormOps.Box(20,20,20,1,1,1);var partial=smooth.Clone();FormOps.SetCrease(partial,partial.Edges(),.35);
var refinedSmooth=smooth.Refine(out _);var refinedPartial=partial.Refine(out _);
Check((refinedPartial.V[0]-partial.V[0]).Length>0 && (refinedPartial.V[0]-partial.V[0]).Length<(refinedSmooth.V[0]-smooth.V[0]).Length,"fractional sharpness remains gradual where three creased edges meet");
panelWindow.Close();window.Close();Console.WriteLine($"SUCCESS: {checks} checks; previews in {output}");

sealed class TestApp:Application{public override void Initialize(){Styles.Add(new FluentTheme());Styles.Add(new StyleInclude(new Uri("avares://Prism/")){Source=new Uri("avares://Prism/Styles/Theme.axaml")});}}
static class Native{[DllImport("kernel32",CharSet=CharSet.Unicode)]static extern bool SetDllDirectory(string path);public static void Initialize()=>SetDllDirectory(Path.GetFullPath("native/bin"));}
